                {
                  heroExcluded={"San'layn"},
                  heroRequired={"Deathbringer"},
                  text="Cast {195182} on single target if you have an {441378} proc available and {49028} is not up. Exterminate rules {441378}'s scythes are not copied by {49028} and they do not cause {55078} to be applied by them either. In practice, this means that using them in {49028} when you are not going to overcap them boils down to a difficult balance between the upfront damage of {206930} vs. {195182} and the number of {1264405} stacks, since they will buff the upfront scythe hits. A simple ruleset is as follows: On single target, use {441378} charges freely in or out of {49028} but treat them as a low-priority filler similar to {50842}. In AoE, use {441378} strictly outside of {49028} where possible",
                },
                {
                  heroExcluded={"San'layn"},
                  heroRequired={"Deathbringer"},
                  text="Cast {195182} in AoE if you have an {441378} proc available. Exterminate rules {441378}'s scythes are not copied by {49028} and they do not cause {55078} to be applied by them either. In practice, this means that using them in {49028} when you are not going to overcap them boils down to a difficult balance between the upfront damage of {206930} vs. {195182} and the number of {1264405} stacks, since they will buff the upfront scythe hits. A simple ruleset is as follows: On single target, use {441378} charges freely in or out of {49028} but treat them as a low-priority filler similar to {50842}. In AoE, use {441378} strictly outside of {49028} where possible",
