        rotation={
          all={
            all={
              steps={
                "Keep {33763} on yourself. We self-cast because we will be stacking healing modifiers on ourselves, which means our Apex healing ({1244331}) will also be much larger. You will also want to keep 1-2 {774} on yourself in order to proc {274902}.",
                "Keep {145205} under a group of players. Due to the {1217941} talent, our {145205} will follow the target of our {33763} (that's us!)",
                "Cast {18562} on cooldown on yourself, and follow it with {774}. This will put {774} on 3 targets due to the {392302} talent. Self-casting will also put a powerful {439530} HoT which increases our healing received by 20%, and thus our Apex healing by the same amount.",
                "Cast {48438} during periods of heavy damage. It is very expensive, and will be the primary spell you spend your mana on. If you are running out of mana a lot, then cast less {48438}.",
                "{740} extends all heal-over-time effects by 10 seconds (via the {197721} talent).",
                "{391528} has a 45% chance to extend all heal-over-time effects by 2 seconds (via the {197721} talent).",
                "{29166}: Restores 25% of your maximum mana. Cast your first at ~75% mana and try and maximize casts through the fight.",
                "{102342}: Reduces the damage a target takes by 20%. Build a habit of using this often because the cooldown is quite low and it is off the global cooldown.",
                "{1126}: This is our \"Raid Buff\" and it's very powerful. Cast this before every boss.",
                "{106898}: An AoE movement speed increase that you might use during specific boss mechanics.",
                "{22812}: Your personal defensive ability. Very low cooldown so use this whenever you're in danger.",
                "{20484}: An in-combat resurrection ability. Combat resurrections are in a shared pool and will recharge over a boss fights duration.",
              },
            },
            aoe={
              steps={
                "Keep {145205} under as many players as you are able. If you have the {1217941} talent, then it will automatically follow the target of your {33763}.",
                "Keep {33763} on a tank or a player taking heavy damage. If the tank is not near the party, and you are using {1217941} then put it on a more central player so that you don't lose {145205} value. Remember that this player will get a ton of healing via {392167}.",
                "Cast {18562} on cooldown and follow it with {774} if the party is quite healthy, or {8936} if they are struggling to stay alive. The choice is between better setup for later, or more healing now. Either way you will proc your {1244470} talent and heal everyone for a lot.",
                "Cast {48438} on cooldown to cover light to moderate party damage.",
                "When nobody is hurt and you do not expect that to change soon you can cast DPS spells to speed up the dungeon. We will cover that in the \"Damage Rotation\" tab because we have a few choices over how we do that.",
                "Make sure {33763} and {145205} are up before the damage hits.",
                "Prepare for the damage ahead of time by casting {774} on DPS in the party. You want five active during all dangerous damage in order to gain the {207383} buff.",
                "Cast {18562} -> {8936} as damage hits. Your {8936} will hit three targets.",
                "Follow up with more {8936} casts until the danger has passed.",
                "If the damage is sharp and instant, then {8936} the target. This is a great time to pair the cast with {132158} if it is available. Continue to cast {8936} until they are safe.",
                "For semi-dangerous damage-over-time effects you should cast 1-2 {774} on the target before you start casting {8936}. If the damage is very dangerous then move over {33763} too. Targets with {33763} are much safer and are nigh-immortal. This is particularly good for mechanics that announce their target in advance - since that gives you more setup time and moving {33763} becomes easier.",
              },
            },
            pvp={
              steps={
                "Always maintain two {774}s on your teammates taking damage.",
                "Use {33763}.",
                "Use {18562}. This is great instant healing and gives you the {158478} buff. With {102693}, this will summon a treant that will cast {50464} on your teammate.",
                "If you are playing Keeper of the Grove, these treants will also use {8921} on an enemy and increase your healing by 5% while they are active.",
                "Use {48438}. With the PvP talent {428937}, this talent should be instant.",
                "Use {378081} to make your next {8936} instant and cost no Mana. Use this when you have a {158478} buff.",
                "If {378081} is not available, cast {8936} with the {158478} buff.",
                "Use {740} to place another HoT on your teammates (this results in you doing more healing from {77495}).",
                "Note: with {392356} talent, every 4th {18562} grants {33891}. When this happens, you will want to use your empowered {8936}s to heal through any incoming damage.",
              },
            },
          },
        },
