                {heroRequired={"Chronowarden"},text="Keep {370537} on cooldown and aim to combine it with {370553}."},
                {heroRequired={"Flameshaper"},text="Keep {370537} on cooldown."},
                {heroRequired={"Chronowarden"},text="Use {370553} as often as possible."},
                "Keep {373861} on cooldown as much as possible.",
                "Keep {355936} on cooldown as much as possible to guarantee procs of {1256577}. Remember that you will want to cast this at Rank 1.",
                "Consume {369297}s with {355913} to trigger {1242031}.",
                "Cast as many {364343}s as possible, whenever you have the Essence to do so.",
                "Consume {364343}s with {1256577}. (if you mess up and do not have Merithra's, you can consume them with {366155})",
                "Cast {360995} after finishing a ramp and when you have no Essence available.",
                "Cast {357208} as much as possible between ramps. Use a {443177} proc with {369939} for healing. Line this up with big damage windows when possible.",
                "When you have nothing to do, cast {357208} to trigger {369939} which you can use to help you generate {369297}s.",
                "Consume Essence with {356995} when no healing is needed to regen mana.",
              },
            },
            aoe={
              steps={
                {heroRequired={"Chronowarden"},text="Cast {364343} to prepare for damage."},
                "Keep {373861} on cooldown at all times.",
                "Keep {366155} on your party members when damage is going out to gain extra healing through {376239}.",
                "Cast {355936} at Rank 1 in most cases. Higher ranks can be used in truly emergency situations where players may die without the additional healing.",
                {heroRequired={"Flameshaper"},text="Cast {355913} to trigger {444088} and other effects anytime AoE healing is needed."},
                "When significant spot healing is needed {361469} can be used if you have a {443177} proc. Just keep in mind that this will be very expensive mana wise.",
                "Make frequent use of {357208} for not only damage purposes but to also generate extra {369297} and proc {369939}.",
                "When absolutely no healing is needed, you can consume Essence on {356995} for additional damage.",
                {
                  heroRequired={"Chronowarden"},
                  text="{355936} — With increases to the Dream Breath HoT effect, it can be very beneficial to maintain this HoT on players at all times. With so many {364343}s at your disposal, it should not be overly difficult to {364343} this ability on cooldown.",
                },
                {
                  heroRequired={"Flameshaper"},
                  text="{355936} — With {444088} being buffed, this ability now becomes your most important one to {364343}. When you have both {355936}s on players, {355913} will trigger the {444088} on both, leading to massive burst healing. You should aim to always {364343} {355936} when it is off cooldown.",
                },
                "{1256577} — This ability will proc from spending Essence and after casting {355936}. When you consume {364343} with this ability, you gain a ton of burst healing while also placing {366155} on every player who had {364343} on them. This gives every benefit of {366155} (think {378196}). This is your easiest way to get good group healing and maintain {366155}s.",
                "{360995} — Using this ability to consume your {364343} will allow you to do quick burst healing. Due to Evoker struggling with single-target healing specifically, being able to Echo this ability during difficult moments will be very valuable.",
                "{366155} — Keeping the passive healing on your will make every pack more manageable, as well as providing the {376239} buff. Thanks to {378196}, it can be very powerful in terms of overall healing and also dealing with burst damage. After your party takes large damage, Golden Hour by itself can provide a ton of extra healing. Generally, you will be getting all of these effects from {1256577} which means that you won't cast as many {366155}s as you did in previous expansions. It falls behind {360995} for that reason as well.",
              },
            },
            pvp={
              steps={
                "{357208} deals damage and puts a DoT on the target. The longer you channel it, the more initial damage it will deal. However, it will weaken the DoT. Ideally, you will channel this to rank 3 because the DoT is normally dispelled and will not deal much damage. Use {370553} with this if you want to deal a large amount of damage to enemies that are grouped up. Note: This spell is normally used with {370553} because of the PvP talent {378438}. This will purge multiple beneficial magic buffs that the enemy team has.",
                "{355936} heals your teammates in front of you and puts a HoT on them. Like {357208}, the longer you channel this spell, the weaker the HoT. Ideally, you will want to use {364343} on your teammate right before you use this spell so that you get the HoT twice.",
              },
            },
          },
        },
