        rotation={
          all={
            all={
              steps={
                {heroRequired={"Oracle","Voidweaver"},text="Refresh your {589} if it would fall off before the end of your Ramp window"},
                {heroRequired={"Oracle","Voidweaver"},text="Cast a {17}"},
                {heroRequired={"Oracle","Voidweaver"},text="Cast a {2061}"},
