                {heroRequired={"Oracle","Voidweaver"},text="Cast {194509} 1-2 times depending on coverage needed"},
                "Cast {32379}",
                {heroRequired={"Oracle","Voidweaver"},text="Cast {8092}"},
                {heroRequired={"Oracle","Voidweaver"},text="Cast {47540}"},
                {heroRequired={"Oracle","Voidweaver"},text="Cast {280749}"},
                {heroRequired={"Oracle"},text="Cast {585} until {47540}/{17} is available again"},
                {heroRequired={"Voidweaver"},text="Cast {450405} until {47540} is available again"},
              },
            },
            aoe={
              steps={
                "Cast {589} if not present on your active target",
                {heroRequired={"Voidweaver"},text="Cast {8092} to access {447444} and proc {280749}"},
                {heroRequired={"Oracle"},text="Cast {8092} for a small burst of damage and to proc {280749}"},
                "Cast {47540} if available",
                "Cast {1253593} if available",
                "Cast {32379}",
                {heroRequired={"Voidweaver"},text="Cast {450405} until one of the above spells is available"},
                "Cast {186263} if a player needs single target healing and Atonement isn't enough",
                {heroRequired={"Oracle"},text="Cast {585} if nothing else is available/no one is in danger"},
                "{472433} - Evangelism accomplishes two things in keys; Making it easier to apply Atonement to the group via both its initial heal on cast as well as making future {194509} casts instant and activating {197862} giving you a temporary boost to your healing and absorption effects. If you find yourself in need of immediate Atonement coverage on the group or need the healing increase, feel free to hit this button. Coming in at a 1:30 cooldown, you should be pressing it fairly often, so don't get caught in the common trap of sitting on it for too long.",
                {
                  heroRequired={"Oracle"},
                  text="{421453} - Uppies comes in as one of the longest cooldowns in the game at 4 minutes with a power level that isn't exactly proportional. You will mainly utilize this button as a gap fill CD when you have nothing available. Its general use case will be targeting an enemy when you have Atonement on your group to benefit from the Atonement healing. It does provide a very large personal shield allowing you to use it as a major defensive as well.",
                },
                {
                  heroRequired={"Voidweaver"},
                  text="{421453} - Uppies comes in as one of the longest cooldowns in the game at 4 minutes and is incredibly powerful if used correctly. A note on using this spell as Voidweaver is that {450612}'s amp to {47540} also applies to Uppies. As a result, it is incredibly important to make sure you cast {8092} and open an {447444} prior to casting Uppies for it to be used at its full power. This spells general use case will be targeting an enemy when you have Atonement on your group to benefit from the Atonement healing. It does also provide a very large personal shield allowing you to use it as a major defensive as well.",
                },
                "{33206} - With {373035} talented, you have an incredibly high number of Pain Suppression charges available over the course of a full dungeon. With this spell being as powerful as it is, make sure you are using it fairly liberally on any target that's taking significant single target damage. Also don't be afraid to use it on yourself if the situation calls for it due to your own defensives being fairly lackluster.",
              },
            },
            pvp={
              steps={
                "Ensure {81749} is on your teammates before dealing any damage to enemy players.",
                "Make sure {589} is on your target.",
                "Use {47540} on the enemy kill target. With {472568}, your {589} will spread to nearby enemies.",
                "Use {10060} on a DPS teammate. With the talent {373466}, you will also gain {10060}.",
                "Use {34433}, {451234} if you are Voidweaver.",
                "Use {32379} if your target drops below 20% health.",
                "Use {47540} as soon as it is off cooldown. Ideally you want to have a {198068} proc ready to empower your {47540}. However, you should still use {47540} if you do not have one.",
                "Use {421453}. Important note: {421453} does not hit targets that are in crowd control. If you want to maximize your damage output with it, use it when the kill target is in a stun and all other enemies are in crowd control!",
                "Use {8092} as soon as it is off cooldown.",
                "Use {585} when all of the above is done, and your spells are rotating back off cooldown.",
              },
            },
          },
