            pvp={
              steps={
                "{34914} and {589} are your two primary DoTs that should be used on as many enemies as possible. These are both the primary abilities that will generate your Insanity. You can use abilities, such as {1227280}, to instantly place these DoTs after a healer dispels them.",
                "{8092} is cast and generates Insanity. This should be used when you have multiple enemies with your DoTs on them to take advantage of the passive {341491}. From {375888}, {589} has a chance to cause your next {8092} to be instant. Use these procs as often as possible.",
                "{391090} causes your {15407} to increase your critical strike chance of {8092}, stacking up to 12 times. If possible, try to use {15407} to maintain this buff often throughout an arena match.",
                "{373202} gives {8092} a chance to make your next {335467} cost no Insanity and deal extra damage. This is another important reason to use your {8092}s as often as possible.",
                "{15407} generates Insanity over the duration it is channeled. This is a filler spell that should be used when you have DoTs on all enemies and {8092} is on cooldown. This will also give you and maintain the buff from {391090}.",
                "{34433} generate Insanity each time the Shadowfiend attacks. This has a long cooldown but can be used in times when you cannot cast to get DoTs on enemies. This can be used with {228260} to increase your burst damage. Note: Shadowfiend gets turned into {451234} if you are playing Voidweaver hero talents.",
                "{1227280} generates Insanity after using it.",
                "If you are Voidweaver, {263165} channels damage on the target and will generate 24 Insanity over the duration it is channeled.",
                "If you are Archon, {120517} generates a small amount of Insanity.",
                "{280752} is a passive ability. This makes it so your {528}, {32375}, {15286}, and {17} all generate Insanity when they are successful.",
