            },
            ["aoe-opener"]={
              steps={
                "Open from Stealth with {703}. Cast it twice for maximum Pandemic value on {381632}",
                "Cast {51723} to generate Combo Points",
                "Cast {1943} with 5+ Combo Points",
                "Cast {360194}, and use any potions, on-use trinkets, or racials here.",
                "Cast {385627}",
                "Cast {32645} at 5+ Combo Points",
                "Cast {1247227} repeatedly to spread your bleeds to all targets. Stop at 5+ CP or when all targets have all bleeds.",
                {heroRequired={"Fatebound"},text="Continue casting {32645} at 5+ CP, and use {51723} to build CP."},
                {
                  heroRequired={"Deathstalker"},
                  text="Continue casting {32645} at 5+ CP, and use {51723} to build CP. Make sure to cast Envenom at 7 CP when {457058} is active.",
                },
              },
            },
            pvp={
              steps={
                "From {1784} or when {108208} is active, there are 3 ways to generate Combo Points: {1833} stuns the target and generates 1 Combo Point.",
                "{8676} can only be used in Stealth or with a {328085} proc, but it does not deal much damage and only generates 2 Combo Points. You will want to use {1329} or {51723} instead.",
                "{703} silences the target and generates 1 Combo Point (3 if you have the talent {385478}.",
                "Using {1833} will stun the enemy and generate 1 combo point.",
                "When not in Stealth, you generate Combo Points with the following: {1329} deals moderate damage and generates 2 Combo Points. It can critically strike with only one hand or with both. That means this ability can generate up to 4 Combo Points with {14190}, one additional Combo Point per hand that critically strikes.",
                "{703} generates 1 Combo Point.",
                "{5938} generates 1 Combo Point. It will also apply a stronger form of your {3408} to the target.",
                "{51723} is an AoE ability and will generate 1 Combo Point plus 1 Combo Point per critical hit with {14190}. It can be used when multiple enemies, including pets, are around you if you want to generate multiple Combo Points. However, it will usually be better to {1329} your main target if they are in range. Be careful not to break crowd control, such as {118}, when using {51723}.",
                "{185565} does very little damage but generates 1 Combo Point and applies all your active poisons to the target. This should be used if you are slowed/rooted and cannot reach your target but are about to overcap Energy or if an enemy at range needs to be slowed.",
                "{1247227} hits all enemies within 10 yards and copies your longest {703}/ {1943} to other enemies. This will also generate 1 Combo Point.",
                "{385627} generates 1 Combo Point baseline. It also generates 5 Combo Points through {1265387}.",
              },
            },
