        rotation={
          all={
            pvp={
              steps={
                "From {1784}, there are two ways to generate Combo Points: {1833} stuns the target and generates 1 Combo Point.",
                "{8676} can only be used in Stealth as well. It deals damage and generates 2 Combo Points, 3 with {381620}.",
                "When not in Stealth, you generate Combo Points with the following: {1752} deals moderate damage and generates 1 Combo Point. It has a 35% chance to strike an additional time, granting a second Combo Point.",
                "{185763} generates 1 Combo Point. It will generate 2 Combo Points instead, if you have an {279876} proc, which you get when {1752} hits an additional time and are playing the talent {196938}.",
                "{8676} can be used from out of Stealth with {381845} procs. It deals damage and generates 2 Combo Points; 3 with {381620}.",
                "{14161} has a 20% chance per Combo Point spent to grant 1 Combo Point. Using a Finishing Move with 5 Combo Points will, therefore, automatically grants 1 Combo Point. Be aware that using a Finishing Move with 6 Combo Points when playing with the {193531} and/or {394321} talents, has a 20% chance to grant 2 Combo Points if you had 6, and a 40% chance if you had 7.",
              },
            },
            ["single-target"]={
              steps={
                "Your rotational priority is virtually the same in single-target and AoE. The only difference is the usage of {13877}. You will want to use BF on cooldown whenever there is a second target in cleave range, but try to use it at low Combo Points to gain the full benefit of {381878}. You want to open from stealth with Blade Flurry in AoE",
                "Use {315508} on cooldown unless you are already in Stage 2 or higher.",
                "Use {381989} when you are in Stage 3. If your next {315508} is unlikely to be used alongside {256170}, you can KIR at Stage 2 as well.",
                "Use {13750} on cooldown, at low Combo Points.",
                "Use {271877} on cooldown as if it were a regular builder (if talented).",
                "Cast {315341} on cooldown with 6+ CP.",
                "Use {1277933} to reset the cooldown of your AR, BtE, and Blade Rush.",
                "Use {51690} on cooldown, at 6+ Combo Points. Always make sure to cast it while {470347} is active.",
                {
                  heroRequired={"Fatebound"},
                  text="Cast {2098} as your main finisher with 5+ CP if no other finishers are available to be used.",
                },
                {
                  heroRequired={"Trickster"},
                  text="Cast {2098} as your main finisher with 6+ CP if no other finishers are available to be used.",
                },
                "Cast {185763} if you have 6 stacks of {279876}. If you have 3 stacks, use it at 1-3 CPs only.",
                "Cast {1752} to generate Combo Points.",
              },
            },
            ["single-target-opener"]={
              steps={
                "Always try to open from {1784} so you can be closer to the boss on pull, and to have {315584} active.",
                "Cast {13750}, {315508}, and {315496} immediately before the pull. SnD will not consume {470347}. (If RtB and SnD are already up, do not use them in your opener)",
                "Use {13877} if there is any cleave opportunity.",
                "Open with {271877} (if talented) or {1752}. Use your DPS potion, racial, and any on-use trinket you might have.",
                "Build Combo Points with {1752}",
                "Use {315341} at 6+ CP",
                "Build CP with {1752} or {185763} if you have 3 or more {381846} stacks",
                "Build CP with {1752} or {185763} if you have 3 or more FtH stacks",
                "Cast {51690} at 6+ CP, even if BTE reset its cooldown.",
                "Use {1277933} if {315341} is on cooldown, otherwise build up to and use BTE again until it goes on cooldown.",
              },
            },
          },
        },
