                "{197835} is an AoE ability and will generate 1 Combo Point for each target hit. Weirdly enough, in PvP, this does not work on pets, only players. You can use this when two players or more are stacked, and you need to generate Combo Points. Be careful not to break crown control, such as Polymorph, when using this ability.",
